SELECT [q].[QuestionSetId], [q].[Name], ( SELECT COUNT(*) FROM [Questions] AS [q0] WHERE [q].[QuestionSetId] = [q0].[QuestionSetId]) AS [QuestionCount], [q].[CreatedAt], [q].[UpdatedAt], ( SELECT COUNT(*) FROM [QuestionRequests] AS [q1] INNER JOIN [QuestionRequestRecipients] AS [q2] ON [q1].[QuestionRequestId] = [q2].[QuestionRequestId] WHERE [q].[QuestionSetId] = [q1].[QuestionSetId]) AS [TotalRecipients], ( SELECT COUNT(*) FROM [QuestionRequests] AS [q3] INNER JOIN [QuestionRequestRecipients] AS [q4] ON [q3].[QuestionRequestId] = [q4].[QuestionRequestId] WHERE [q].[QuestionSetId] = [q3].[QuestionSetId] AND EXISTS ( SELECT 1 FROM [QuestionResponses] AS [q5] WHERE [q4].[QuestionRequestRecipientId] = [q5].[QuestionRequestRecipientId])) AS [RespondedRecipients], ( SELECT TOP(1) [q8].[AnsweredAt] FROM [QuestionRequests] AS [q6] INNER JOIN [QuestionRequestRecipients] AS [q7] ON [q6].[QuestionRequestId] = [q7].[QuestionRequestId] INNER JOIN [QuestionResponses] AS [q8] ON [q7].[QuestionRequestRecipientId] = [q8].[QuestionRequestRecipientId] WHERE [q].[QuestionSetId] = [q6].[QuestionSetId] ORDER BY [q8].[AnsweredAt] DESC) AS [LatestAnswer], ( SELECT TOP(1) [q9].[CreatedAt] FROM [QuestionRequests] AS [q9] WHERE [q].[QuestionSetId] = [q9].[QuestionSetId] ORDER BY [q9].[CreatedAt] DESC) AS [LatestSend] FROM [QuestionSets] AS [q] WHERE [q].[UserId] = @__userId_0 AND [q].[Archived] = CAST(0 AS bit)